export function buildProjectMediaTubeItems(projectId: string): ProjectMediaTubeItem[] {
  const cleanProj = (projectId || 'SEVEN').toUpperCase();
  const baseKinds: Array<'image' | 'video' | 'pdf'> = ['video', 'pdf', 'image', 'video'];
  const baseAspects: Array<'16:9' | '4:3' | '1:1' | 'A4'> = ['16:9', '16:9', '16:9', 'A4'];
  const timelinePhases = VIDEO_180S_STAGGER_TIMELINE;
  const baseTitles = [
    `${cleanProj} · 06 One-Shot Master Treatment & Camera Choreography`,
    `${cleanProj} · 07 180s Frame-by-Frame Stagger Timeline (10,800f @ 60fps)`,
    `${cleanProj} · 08 Video Motion Tokens & GLSL Shader Rig`,
    `${cleanProj} · Phase 1 [${timelinePhases[0].timeWindow}] ${timelinePhases[0].cameraLens} Ignition`,
    `${cleanProj} · Phase 2 [${timelinePhases[1].timeWindow}] ${timelinePhases[1].cameraLens} HQ Orbit`,
    `${cleanProj} · Phase 3 [${timelinePhases[2].timeWindow}] ${timelinePhases[2].cameraLens} Macro SEVEN`,
    `${cleanProj} · Phase 4 [${timelinePhases[3].timeWindow}] ${timelinePhases[3].cameraLens} Whip-Pan CDE`,
    `${cleanProj} · Phase 5-6 [${timelinePhases[4].timeWindow}] ${timelinePhases[5].cameraLens} Zenith Pullback`,
  ];

  return Array.from({ length: PROJECT_MEDIA_TUBE_SPECS.maxMountedTiles }).map((_, idx) => {
    const kind = baseKinds[idx % baseKinds.length];
    const aspect = baseAspects[idx % baseAspects.length];
    const row = Math.floor(idx / PROJECT_MEDIA_TUBE_SPECS.columns) + 1;
    const col = (idx % PROJECT_MEDIA_TUBE_SPECS.columns) + 1;
    const accentHex =
      kind === 'video' ? '#4C8DFF' : kind === 'pdf' ? '#5CC8D7' : '#F2B66D';
    return {
      index: idx,
      id: `tube-${cleanProj.toLowerCase()}-${String(idx + 1).padStart(2, '0')}`,
      projectId: cleanProj,
      title: `${baseTitles[idx % baseTitles.length]} (${row}.${col})`,
      subtitle: `CDE 2030 · ${kind.toUpperCase()} · Row ${row} Col ${col} · ${aspect}`,
      kind,
      aspect,
      accentHex,
    };
  });
}

