export const CARDIAC_BEAM_FRAGMENT_SHADER = /* glsl */ `
  uniform float uTime;
  uniform vec3 uSplineColor;
  uniform float uDimFactor;
  varying vec2 vUv;

  void main() {
    float phase = fract(vUv.x - uTime * 0.45);
    float c1 = exp(-pow((phase - 0.30) / 0.045, 2.0));
    float c2 = 0.65 * exp(-pow((phase - 0.42) / 0.065, 2.0));
    float pulse = clamp(c1 + c2, 0.0, 1.0);
    vec3 col = mix(uSplineColor * 0.35, vec3(0.95, 0.98, 1.0), pulse);
    float alpha = (0.28 + 0.72 * pulse) * uDimFactor;
    gl_FragColor = vec4(col, alpha);
  }
`;

